const body = $json.body ?? $json;
const invoice = body.invoice ?? {};
const customer = body.customer ?? {};
const business = body.business ?? {};
const legal = body.legal ?? {};

const total = Number(invoice.total ?? 0);
const dpPercent = Number(invoice.dp_percent ?? 60);
const dpAmount = Number(invoice.dp_amount ?? Math.round(total * dpPercent / 100));
const balancePercent = Number(invoice.balance_percent ?? 40);
const balanceAmount = Number(invoice.balance_amount ?? total - dpAmount);

const rupiah = value => new Intl.NumberFormat('id-ID', {
  style: 'currency',
  currency: 'IDR',
  maximumFractionDigits: 0
}).format(Number(value || 0));

return [{ json: {
  invoice_id: body.invoice_id ?? '',
  order_id: body.order_id ?? '',
  customer_name: customer.name ?? '',
  customer_email: customer.email ?? '',
  business_name: business.name ?? '',
  legal_package: legal.package ?? '',
  kbli_code: legal.kbli_code ?? '',
  kbli_name: legal.kbli_name ?? '',
  total_rupiah: rupiah(total),
  dp_percent: dpPercent,
  dp_rupiah: rupiah(dpAmount),
  balance_percent: balancePercent,
  balance_rupiah: rupiah(balanceAmount),
  payment_status: invoice.payment_status ?? 'DP_PENDING',
  invoice_pdf_url: body.invoice_pdf_url ?? ''
}}];
